parameters.functionCode:
// Find high-priority domains needing attention
const projects = $input.all()[0].json.projects || [];
const opportunities = [];

for (const project of projects) {
  if (project.status !== 'active') continue;

  for (const domain of project.domains || []) {
    // High priority: progress < 25% or status = in-progress + progress < 50%
    const priority = domain.progress < 25 ? 'high' : 
                     (domain.status === 'in-progress' && domain.progress < 50) ? 'medium' : 'low';

    if (priority === 'high' || priority === 'medium') {
      opportunities.push({
        projectId: project.id,
        projectName: project.name,
        domainSlug: domain.slug,
        domainName: domain.name,
        progress: domain.progress,
        priority,
        features: domain.features || [],
        description: domain.description
      });
    }
  }
}

// Sort by priority
opportunities.sort((a, b) => {
  const priorityOrder = { high: 0, medium: 1, low: 2 };
  return priorityOrder[a.priority] - priorityOrder[b.priority];
});

return opportunities.map(opp => ({ json: opp }));

// Assign optimal crew based on domain type
const opportunity = $input.item.json;

// Crew specialization mapping
const crewAssignments = {
  // AI/ML domains
  'ai-engine': ['commander_data', 'geordi_la_forge'],
  'rag-memory-system': ['commander_data', 'geordi_la_forge', 'quark'],
  'collaboration-engine': ['commander_riker', 'commander_data', 'counselor_troi'],

  // Infrastructure
  'infrastructure': ['geordi_la_forge', 'chief_obrien'],
  'deployment': ['geordi_la_forge', 'lieutenant_worf'],

  // Security
  'security': ['lieutenant_worf', 'commander_data'],
  'authentication': ['lieutenant_worf', 'geordi_la_forge'],

  // UI/UX
  'ui': ['counselor_troi', 'lieutenant_uhura'],
  'dashboard': ['counselor_troi', 'chief_obrien'],

  // Business
  'monetization': ['quark', 'captain_picard'],
  'cost-optimization': ['quark', 'geordi_la_forge']
};

// Find best crew match
let assignedCrew = null;
for (const [key, crew] of Object.entries(crewAssignments)) {
  if (opportunity.domainSlug.includes(key) || 
      opportunity.domainName.toLowerCase().includes(key)) {
    assignedCrew = crew;
    break;
  }
}

// Default to generalist team
if (!assignedCrew) {
  assignedCrew = ['commander_riker', 'chief_obrien', 'counselor_troi'];
}

return {
  json: {
    ...opportunity,
    assignedCrew,
    teamSize: assignedCrew.length
  }
};

// Optimize LLM selection based on task complexity
const item = $input.item.json;

// Cost-optimized model selection
// Haiku: $0.25/$1.25 per 1M tokens (cheapest)
// GPT-4 Turbo: $10/$30 per 1M tokens
// Claude 3.5 Sonnet: $3/$15 per 1M tokens

const modelAssignments = {
  // Simple tasks → Haiku
  simple: 'anthropic/claude-3-haiku',

  // Medium complexity → GPT-4 Turbo or Sonnet
  medium: 'openai/gpt-4-turbo',

  // High complexity or strategic → Sonnet
  complex: 'anthropic/claude-3.5-sonnet',

  // Analysis heavy → GPT-4
  analysis: 'openai/gpt-4-turbo'
};

// Determine task complexity
let complexity = 'medium';
if (item.priority === 'high' && item.progress < 15) {
  complexity = 'complex'; // New domains need strategic thinking
} else if (item.features && item.features.length > 5) {
  complexity = 'complex'; // Many features = complex
} else if (item.progress > 50) {
  complexity = 'simple'; // Later stage work is often simpler
}

// Assign models per crew member based on their role
const crewModels = {};
for (const crewId of item.assignedCrew) {
  if (crewId === 'captain_picard' || crewId === 'commander_riker') {
    crewModels[crewId] = modelAssignments.complex; // Leaders get best models
  } else if (crewId === 'commander_data' || crewId === 'quark') {
    crewModels[crewId] = modelAssignments.analysis; // Analysts get GPT-4
  } else {
    crewModels[crewId] = modelAssignments[complexity];
  }
}

return {
  json: {
    ...item,
    crewModels,
    estimatedCost: calculateCost(crewModels)
  }
};

function calculateCost(models) {
  const costs = {
    'anthropic/claude-3-haiku': 0.001, // $0.001 per 1K tokens (avg)
    'openai/gpt-4-turbo': 0.020,       // $0.020 per 1K tokens (avg)
    'anthropic/claude-3.5-sonnet': 0.009 // $0.009 per 1K tokens (avg)
  };

  let total = 0;
  for (const model of Object.values(models)) {
    total += costs[model] || 0.010;
  }

  return total;
}

// Parse collaboration results and update project
const result = $input.item.json;

return {
  json: {
    timestamp: new Date().toISOString(),
    projectId: result.projectId,
    domainSlug: result.domainSlug,
    crew: result.assignedCrew,
    insights: result.insights || [],
    progressDelta: result.progressDelta || 0,
    tokenUsage: result.tokenUsage || {},
    cost: result.cost || 0,
    success: true
  }
};

